WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
CONNECT -name IMART
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED
SET SQLFORMAT ANSICONSOLE
SET LINESIZE 200
SPOOL logic-tests.log
declare
 d date:=trunc(cast(systimestamp at time zone 'Asia/Kolkata' as date));
 procedure run_case(p_name varchar2,p_quick varchar2,p_from varchar2,p_to varchar2,p_grain varchar2,p_expected_from varchar2,p_expected_to varchar2,p_error boolean default false) is
 c integer;ret integer;f varchar2(100):=p_from;t varchar2(100):=p_to;g varchar2(100):=p_grain;k varchar2(100):=p_quick;
 begin
 c:=dbms_sql.open_cursor;
 dbms_sql.parse(c,q'!declare f date;t date;d date:=trunc(cast(systimestamp at time zone 'Asia/Kolkata' as date));begin
 if :REQUEST='CLEAR' then
 apex_util.set_session_state('P1100_FROM',null);
apex_util.set_session_state('P1100_TO',null);
apex_util.set_session_state('P1100_COMPANY',null);
apex_util.set_session_state('P1100_LOCATION',null);
apex_util.set_session_state('P1100_USER',null);
apex_util.set_session_state('P1100_EMPLOYEE',null);
apex_util.set_session_state('P1100_DEPARTMENT',null);
apex_util.set_session_state('P1100_MODULE',null);
apex_util.set_session_state('P1100_PAGE',null);
apex_util.set_session_state('P1100_ACTION',null);
apex_util.set_session_state('P1100_OUTCOME',null);
apex_util.set_session_state('P1100_SOURCE',null);
apex_util.set_session_state('P1100_TABLE',null);
apex_util.set_session_state('P1100_RECORD',null);
 :P1100_QUICK:='TODAY';:P1100_GRAIN:='DAY';end if;
 case nvl(:P1100_QUICK,'CUSTOM') when 'TODAY' then f:=d;t:=d;when 'YESTERDAY' then f:=d-1;t:=d-1;when 'WEEK' then f:=trunc(d,'IW');t:=d;when 'MONTH' then f:=trunc(d,'MM');t:=d;when 'PREVIOUS' then f:=add_months(trunc(d,'MM'),-1);t:=trunc(d,'MM')-1;when 'CUSTOM' then f:=case when validate_conversion(:P1100_FROM as date,'FXDD-MM-YYYY')=1 then to_date(:P1100_FROM,'FXDD-MM-YYYY') when validate_conversion(:P1100_FROM as date,'FXYYYY-MM-DD')=1 then to_date(:P1100_FROM,'FXYYYY-MM-DD') end;t:=case when validate_conversion(:P1100_TO as date,'FXDD-MM-YYYY')=1 then to_date(:P1100_TO,'FXDD-MM-YYYY') when validate_conversion(:P1100_TO as date,'FXYYYY-MM-DD')=1 then to_date(:P1100_TO,'FXYYYY-MM-DD') end;else raise_application_error(-20840,'Invalid quick date selection');end case;
 if f is null or t is null or t<f or t-f>365 then raise_application_error(-20840,'Choose a valid period of at most 366 days.');end if;
 if :P1100_GRAIN not in ('HOUR','DAY','MONTH') or :P1100_GRAIN is null then raise_application_error(-20840,'Choose Hour, Day or Month.');end if;
 :P1100_FROM:=to_char(f,'DD-MM-YYYY');:P1100_TO:=to_char(t,'DD-MM-YYYY');
end;!',dbms_sql.native);
 dbms_sql.bind_variable(c,':REQUEST','APPLY');
 dbms_sql.bind_variable(c,':P1100_QUICK',k,100);
 dbms_sql.bind_variable(c,':P1100_GRAIN',g,100);
 dbms_sql.bind_variable(c,':P1100_FROM',f,100);
 dbms_sql.bind_variable(c,':P1100_TO',t,100);
 begin ret:=dbms_sql.execute(c);
 exception when others then
 if sqlcode=-20840 and p_error then dbms_sql.close_cursor(c);dbms_output.put_line('PASS logic: '||p_name);return;else raise;end if;
 end;
 if p_error then raise_application_error(-20842,'Expected validation error: '||p_name);end if;
 dbms_sql.variable_value(c,':P1100_FROM',f);dbms_sql.variable_value(c,':P1100_TO',t);dbms_sql.close_cursor(c);
 if f<>to_char(to_date(p_expected_from,'YYYY-MM-DD'),'DD-MM-YYYY') or t<>to_char(to_date(p_expected_to,'YYYY-MM-DD'),'DD-MM-YYYY') or f is null or t is null then raise_application_error(-20842,'Date mismatch: '||p_name);end if;
 dbms_output.put_line('PASS logic: '||p_name);
 exception when others then if c is not null and dbms_sql.is_open(c) then dbms_sql.close_cursor(c);end if;raise;
 end;
begin
 run_case('Today','TODAY',null,null,'DAY',to_char(d,'YYYY-MM-DD'),to_char(d,'YYYY-MM-DD'));
 run_case('Yesterday','YESTERDAY',null,null,'HOUR',to_char(d-1,'YYYY-MM-DD'),to_char(d-1,'YYYY-MM-DD'));
 run_case('This week (ISO Monday)','WEEK',null,null,'DAY',to_char(trunc(d,'IW'),'YYYY-MM-DD'),to_char(d,'YYYY-MM-DD'));
 run_case('This month','MONTH',null,null,'DAY',to_char(trunc(d,'MM'),'YYYY-MM-DD'),to_char(d,'YYYY-MM-DD'));
 run_case('Previous month','PREVIOUS',null,null,'MONTH',to_char(add_months(trunc(d,'MM'),-1),'YYYY-MM-DD'),to_char(trunc(d,'MM')-1,'YYYY-MM-DD'));
 run_case('DD-MM input','CUSTOM','20-10-2026','21-10-2026','DAY','2026-10-20','2026-10-21');
 run_case('DD-MM leap day','CUSTOM','29-02-2024','29-02-2024','DAY','2024-02-29','2024-02-29');
 run_case('DD-MM invalid day rejected','CUSTOM','31-02-2026','20-10-2026','DAY',null,null,true);
 run_case('DD-MM ambiguous day order','CUSTOM','04-05-2026','04-05-2026','DAY','2026-05-04','2026-05-04');
 run_case('DD-MM month boundary','CUSTOM','31-10-2026','01-11-2026','DAY','2026-10-31','2026-11-01');
 run_case('Custom leap day','CUSTOM','2024-02-29','2024-02-29','DAY','2024-02-29','2024-02-29');
 run_case('366 inclusive days allowed','CUSTOM','2025-10-20','2026-10-20','DAY','2025-10-20','2026-10-20');
 run_case('Null date rejected','CUSTOM',null,'2026-10-20','DAY',null,null,true);
 run_case('Invalid calendar date rejected','CUSTOM','2026-02-30','2026-10-20','DAY',null,null,true);
 run_case('Inverted range rejected','CUSTOM','2026-10-21','2026-10-20','DAY',null,null,true);
 run_case('367 inclusive days rejected','CUSTOM','2025-10-19','2026-10-20','DAY',null,null,true);
 run_case('Unknown date preset rejected','FORGED',null,null,'DAY',null,null,true);
 run_case('Unknown time grouping rejected','TODAY',null,null,'FORGED',null,null,true);
 run_case('Null time grouping rejected','TODAY',null,null,null,null,null,true);
end;
