declare n number;begin select count(*) into n from (select case when regexp_like(to_char(text_value),'^[[:space:][:cntrl:]]*[=+@-]') then chr(39)||to_char(text_value) else to_char(text_value) end protected_value,chr(39)||'@SUM(A1:A2)' expected from (select '@SUM(A1:A2)' text_value from dual)) where protected_value=expected or (protected_value is null and expected is null);if n<>1 then raise_application_error(-20842,'Formula protection mismatch');end if;dbms_output.put_line('PASS logic: Formula at');end;
/
declare n number;begin select count(*) into n from (select case when regexp_like(to_char(text_value),'^[[:space:][:cntrl:]]*[=+@-]') then chr(39)||to_char(text_value) else to_char(text_value) end protected_value,chr(39)||'  =1+1' expected from (select '  =1+1' text_value from dual)) where protected_value=expected or (protected_value is null and expected is null);if n<>1 then raise_application_error(-20842,'Formula protection mismatch');end if;dbms_output.put_line('PASS logic: Leading whitespace');end;
/
declare n number;begin select count(*) into n from (select case when regexp_like(to_char(text_value),'^[[:space:][:cntrl:]]*[=+@-]') then chr(39)||to_char(text_value) else to_char(text_value) end protected_value,chr(39)||chr(9)||'=1+1' expected from (select chr(9)||'=1+1' text_value from dual)) where protected_value=expected or (protected_value is null and expected is null);if n<>1 then raise_application_error(-20842,'Formula protection mismatch');end if;dbms_output.put_line('PASS logic: Leading tab');end;
