declare n number;begin select count(*) into n from (select case when regexp_like(to_char(text_value),'^[[:space:][:cntrl:]]*[=+@-]') then chr(39)||to_char(text_value) else to_char(text_value) end protected_value,'ABC=2' expected from (select 'ABC=2' text_value from dual)) where protected_value=expected or (protected_value is null and expected is null);if n<>1 then raise_application_error(-20842,'Formula protection mismatch');end if;dbms_output.put_line('PASS logic: Internal equals retained');end;
/
declare n number;begin select count(*) into n from (select case when regexp_like(to_char(text_value),'^[[:space:][:cntrl:]]*[=+@-]') then chr(39)||to_char(text_value) else to_char(text_value) end protected_value,cast(null as varchar2(100)) expected from (select cast(null as varchar2(100)) text_value from dual)) where protected_value=expected or (protected_value is null and expected is null);if n<>1 then raise_application_error(-20842,'Formula protection mismatch');end if;dbms_output.put_line('PASS logic: Null retained');end;
